/**
 * AuthGuard — validates provider-issued tokens against a JWKS endpoint.
 *
 * Uses `jose` `createRemoteJWKSet` + `jwtVerify` with `kid`-based rotation.
 * Algorithm allow-list comes from the resolved identity provider plan.
 * Symmetric algorithms (HS*) and `alg:none` are always rejected.
 * JWKS refresh failure fails closed.
 *
 * Role semantics: flat any-of — the principal must hold at least one of the
 * required roles (no transitive role hierarchy).
 *
 * Auto-generated by datrix-codegen-typescript. Do not edit manually.
 */
import {
  CanActivate,
  ExecutionContext,
  Injectable,
  Logger,
  UnauthorizedException,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import type { Request } from 'express';
import { IS_PUBLIC_KEY } from './public.decorator';
import { ROLES_KEY } from './roles.decorator';
import { verifyIdentityToken } from './identity';
import type { IdentityPrincipal } from './identity';

/** Surface ID key in the endpoint metadata (set by @Surface() decorator). */
export const SURFACE_ID_KEY = 'surface_id';

/** Default surface ID used when no @Surface() decorator is present. */
const DEFAULT_SURFACE_ID = 'order-service';

@Injectable()
export class AuthGuard implements CanActivate {
  private readonly logger = new Logger(AuthGuard.name);

  constructor(private readonly reflector: Reflector) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const isPublic = this.reflector.getAllAndOverride<boolean>(IS_PUBLIC_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (isPublic) {
      return true;
    }

    const request = context.switchToHttp().getRequest<Request>();
    const token = this.extractTokenFromHeader(request);
    if (!token) {
      this.logger.warn(
        `identity_token_validation_failed reason=missing_token path=${request.path}`,
      );
      throw new UnauthorizedException('Authentication required');
    }

    const surfaceId =
      this.reflector.getAllAndOverride<string>(SURFACE_ID_KEY, [
        context.getHandler(),
        context.getClass(),
      ]) ?? DEFAULT_SURFACE_ID;

    let principal: IdentityPrincipal;
    try {
      principal = await verifyIdentityToken(token, surfaceId);
    } catch (err) {
      const reasonMessage =
        err instanceof Error ? err.message : String(err);
      const reasonCode = reasonMessage.includes(':')
        ? reasonMessage.split(':')[0].trim()
        : 'malformed_token';
      this.logger.warn(
        `identity_token_validation_failed reason=${reasonCode} path=${request.path}`,
      );
      throw new UnauthorizedException('Authentication required');
    }

    // Flat any-of role check: resolve required roles from metadata.
    const requiredRoles = this.reflector.getAllAndOverride<string[]>(ROLES_KEY, [
      context.getHandler(),
      context.getClass(),
    ]);
    if (requiredRoles && requiredRoles.length > 0) {
      const hasRole = requiredRoles.some((role) => principal.roles.includes(role));
      if (!hasRole) {
        this.logger.warn(
          `identity_role_or_policy_denied path=${request.path} surface=${surfaceId}`,
        );
        throw new UnauthorizedException('Insufficient permissions');
      }
    }

    // Attach principal to request for downstream handlers.
    (request as unknown as Record<string, unknown>)['user'] = principal;
    this.logger.debug(
      `identity_token_verified surface=${surfaceId} provider=${principal.provider}`,
    );
    return true;
  }

  private extractTokenFromHeader(request: Request): string | undefined {
    const authHeader = request.headers.authorization;
    if (!authHeader) {
      return undefined;
    }
    const [type, token] = authHeader.split(' ');
    return type === 'Bearer' ? token : undefined;
  }
}
